type Extra = Partial<KBEntry>;
const M = (summary: string, origin: string, insertion: string, action: string, innervation: string, blood: string, extra: Extra = {}): KBEntry => ({
  summary, origin, insertion, action, innervation, blood, micro: 'sarcomere', ...extra,
});

